//! Differential parity gate — Rust vs the REAL Python oracle.
//!
//!   make corpus goldens split-goldens && cargo test
//!
//! Inputs: corpus/inputs.bin (NUL-separated records)
//! Goldens: corpus/goldens.txt (tokenize) + corpus/goldens-split.txt (split),
//! generated by tools/oracle.py against the real sqlparse 0.6.0.
//! Both tests SKIP (with a note) when the artifacts are absent, so
//! `cargo test` stays green before the Python side is set up.

use std::fs;
use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read_records(path: &Path) -> Option<Vec<Vec<u8>>> {
    let data = fs::read(path).ok()?;
    let mut recs: Vec<Vec<u8>> = data.split(|&b| b == 0).map(|s| s.to_vec()).collect();
    if recs.last().map(|r| r.is_empty()).unwrap_or(false) {
        recs.pop();
    }
    Some(recs)
}

fn hex_of(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 2);
    for b in s.as_bytes() {
        out.push_str(&format!("{b:02X}"));
    }
    out
}

struct Golden {
    ttype: String,
    hex: String,
}

/// Parse goldens into per-record blocks; None = oracle-error record.
fn parse_goldens(path: &Path) -> Vec<Option<Vec<Golden>>> {
    let text = fs::read_to_string(path).unwrap_or_else(|e| {
        panic!("cannot read {}: {e}", path.display())
    });
    let mut blocks: Vec<Option<Vec<Golden>>> = Vec::new();
    let mut cur: Option<Vec<Golden>> = None;
    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("== rec ") {
            assert!(cur.is_none(), "nested '== rec' without '== end'");
            if rest.contains(" ERROR ") {
                blocks.push(None);
            } else {
                cur = Some(Vec::new());
            }
        } else if line.trim() == "== end" {
            if let Some(b) = cur.take() {
                blocks.push(Some(b));
            }
        } else if let Some(buf) = cur.as_mut() {
            let (ttype, hex) = line
                .split_once('\t')
                .unwrap_or_else(|| panic!("bad golden line: {line:?}"));
            buf.push(Golden {
                ttype: ttype.to_string(),
                hex: hex.to_string(),
            });
        }
    }
    blocks
}

fn parse_split_goldens(path: &Path) -> Vec<Option<Vec<String>>> {
    let text = fs::read_to_string(path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let mut blocks: Vec<Option<Vec<String>>> = Vec::new();
    let mut cur: Option<Vec<String>> = None;
    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("== rec ") {
            assert!(cur.is_none(), "nested '== rec' without '== end'");
            if rest.contains(" ERROR ") {
                blocks.push(None);
            } else {
                cur = Some(Vec::new());
            }
        } else if line.trim() == "== end" {
            if let Some(b) = cur.take() {
                blocks.push(Some(b));
            }
        } else if let Some(buf) = cur.as_mut() {
            // oracle split mode emits bare hex lines (plus a 'count N' header)
            if line.starts_with("count ") {
                continue;
            }
            let bytes: Vec<u8> = (0..line.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&line[i..i + 2], 16).unwrap())
                .collect();
            buf.push(String::from_utf8(bytes).expect("golden stmt utf8"));
        }
    }
    blocks
}

#[test]
fn differential_tokenize_parity() {
    let root = root();
    let inputs = match read_records(&root.join("corpus/inputs.bin")) {
        Some(i) => i,
        None => {
            eprintln!("differential(tokenize): SKIPPED — corpus/inputs.bin missing (run `make corpus goldens`)");
            return;
        }
    };
    let gpath = root.join("corpus/goldens.txt");
    if !gpath.exists() {
        eprintln!("differential(tokenize): SKIPPED — corpus/goldens.txt missing");
        return;
    }
    let blocks = parse_goldens(&gpath);
    assert_eq!(
        inputs.len(),
        blocks.len(),
        "inputs/goldens out of sync — re-run: make corpus goldens"
    );

    let mut compared = 0;
    let mut skipped = 0;
    let mut mismatched = 0;
    let mut first = String::new();

    for (i, input) in inputs.iter().enumerate() {
        let expected = match &blocks[i] {
            Some(b) => b,
            None => {
                skipped += 1;
                continue;
            }
        };
        let text = match std::str::from_utf8(input) {
            Ok(t) => t,
            Err(_) => {
                skipped += 1;
                continue;
            }
        };
        compared += 1;
        let actual = sqlparse_core::tokenize(text);
        let actual: Vec<(&str, String)> =
            actual.into_iter().map(|(t, v)| (t, v.to_string())).collect();

        if actual.len() != expected.len() {
            mismatched += 1;
            if first.is_empty() {
                let mut detail = String::new();
                for k in 0..actual.len().min(expected.len()) {
                    if expected[k].ttype != actual[k].0
                        || expected[k].hex != hex_of(&actual[k].1)
                    {
                        detail = format!(
                            "first differing token #{k}: expected {} {} | got {} {}\n",
                            expected[k].ttype, expected[k].hex, actual[k].0, hex_of(&actual[k].1)
                        );
                        break;
                    }
                }
                first = format!(
                    "record {i}: COUNT expected {} got {}\n{detail}input: {:?}",
                    expected.len(),
                    actual.len(),
                    &text.chars().take(80).collect::<String>()
                );
            }
            continue;
        }
        for (k, e) in expected.iter().enumerate() {
            if e.ttype != actual[k].0 || e.hex != hex_of(&actual[k].1) {
                mismatched += 1;
                if first.is_empty() {
                    first = format!(
                        "record {i} token #{k}: expected {} {} | got {} {}\ninput: {:?}",
                        e.ttype,
                        e.hex,
                        actual[k].0,
                        hex_of(&actual[k].1),
                        &text.chars().take(80).collect::<String>()
                    );
                }
                break;
            }
        }
    }

    eprintln!(
        "differential(tokenize): {compared} compared, {skipped} skipped, {mismatched} mismatched records"
    );
    assert!(first.is_empty(), "FIRST DIVERGENCE:\n{first}");
}

#[test]
fn differential_split_parity() {
    let root = root();
    let inputs = match read_records(&root.join("corpus/inputs.bin")) {
        Some(i) => i,
        None => {
            eprintln!("differential(split): SKIPPED — corpus/inputs.bin missing");
            return;
        }
    };
    let gpath = root.join("corpus/goldens-split.txt");
    if !gpath.exists() {
        eprintln!("differential(split): SKIPPED — corpus/goldens-split.txt missing");
        return;
    }
    let blocks = parse_split_goldens(&gpath);
    assert_eq!(inputs.len(), blocks.len(), "inputs/split-goldens out of sync");

    let mut compared = 0;
    let mut skipped = 0;
    let mut mismatched = 0;
    let mut first = String::new();

    for (i, input) in inputs.iter().enumerate() {
        let expected = match &blocks[i] {
            Some(b) => b,
            None => {
                skipped += 1;
                continue;
            }
        };
        let text = match std::str::from_utf8(input) {
            Ok(t) => t,
            Err(_) => {
                skipped += 1;
                continue;
            }
        };
        compared += 1;
        let actual = sqlparse_core::split(text);
        if actual != *expected {
            mismatched += 1;
            if first.is_empty() {
                first = format!(
                    "record {i}:\n  expected {:?}\n  actual   {:?}",
                    expected.iter().take(3).collect::<Vec<_>>(),
                    actual.iter().take(3).collect::<Vec<_>>()
                );
            }
        }
    }

    eprintln!(
        "differential(split): {compared} compared, {skipped} skipped, {mismatched} mismatched records"
    );
    assert!(first.is_empty(), "FIRST SPLIT DIVERGENCE:\n{first}");
}
